mapper.select:
select * from (select rownum rn, A.* from 
(select * from review2 where rproduct = #{rproduct} order by rnum desc) A)
where rn between #{start} and #{end}

select * from (select rownum rn, A.* from 
(select * from review2 where id = #{id} order by rnum desc) A)
where rn between #{start} and #{end}

select * from (select rownum rn,A.*from
(select * from review2 where ${search} like #{searchString} order by rnum desc)A)
where rn between #{start} and #{end}

select * from (select rownum rn, A.* from 
(select * from review2 order by rnum desc) A)
where rn between #{start} and #{end}
